// This file is not generated by Speakeasy — it decides whether stdin holds a
// request body for BuildRequest and BuildRequestBody, and bounds the read.
//
// The problem it solves: `HasStdinInput` reports true for any non-TTY stdin,
// including a pipe that is open but will never carry data or close. io.ReadAll
// then blocks forever waiting for an EOF that never arrives, so the CLI hangs
// instead of failing. That affects every command with a body — 76 of 138 — and
// it is the worst possible failure for the audience this CLI targets, because a
// coding agent or CI job stalls with no output and nothing to act on.
//
// Two shapes hang, and both are covered here:
//
//	sleep 30 | vf agent update ...          # never writes, never closes
//	( echo '{}'; sleep 30 ) | vf ...        # writes, then holds the write end
//
// Deciding whether to read is done by file type, never by polling for
// readiness. A readiness check cannot distinguish "silent forever" from "slow by
// ten milliseconds" without waiting, and waiting is what it was meant to avoid:
// measured against real producers, a zero-timeout poll discarded the body from
// curl, node and python3 pipelines every single time, which is silent data loss
// dressed up as a fix. Reading with a deadline is slower in the pathological
// case and correct in every other one.
//
// One shape is an exception: a socket, when an AI coding agent runs vf. Claude
// Code runs any Bash command that contains a heredoc with stdin connected to a
// Unix socket that it never writes to and never closes. Every body command in
// such a call waited the full deadline and then failed, even when its flags
// held the whole request. Waiting there protects nothing. Shells hand vf a pipe
// or a file, for `producer | vf`, `vf < file` and heredocs alike, never a
// socket. A socket comes from a program that spawned vf, and a program that
// means to send a body writes it when it starts vf: Node's first byte lands
// within a millisecond, even with a hundred spawns at once. So in agent mode a
// socket that delivers nothing within agentSocketWait is taken to carry no
// body. Pipes and files keep the full deadline in every mode, so a slow
// `curl ... | vf` is still read. A program that must write late can pass the
// body with --body instead.

package flagutil

import (
	"errors"
	"fmt"
	"io"
	"os"
	"sync"
	"time"

	"github.com/spf13/cobra"
)

// StdinReadTimeout bounds how long a command will wait for piped input before
// giving up. Generous on purpose: a producer doing real work first — a network
// fetch, a large transform, another CLI — must comfortably fit inside it, since
// dropping that input silently would be worse than the hang this replaces.
const StdinReadTimeout = 10 * time.Second

// agentSocketWait is how long, in agent mode, a socket on stdin has to deliver
// anything before vf treats it as carrying no body.
const agentSocketWait = 250 * time.Millisecond

// ErrStdinTimeout is returned when stdin stayed open past StdinReadTimeout
// without delivering data or closing.
var ErrStdinTimeout = errors.New("timed out reading stdin")

// isAgentMode reports whether an AI coding agent is running vf. The output
// package owns agent detection and installs its IsAgentMode here when the
// program starts, because output imports flagutil and the reverse import would
// be a cycle. Asking each time, rather than keeping a copy, means flagutil
// always sees the mode as finally resolved.
var isAgentMode = func() bool { return false }

// SetAgentModeCheck installs the function that reports agent mode.
func SetAgentModeCheck(check func() bool) {
	isAgentMode = check
}

// silenceMeansNoBody reports whether stdin of this type, when it stays silent
// for agentSocketWait, carries no body rather than a body still on its way.
func silenceMeansNoBody(isAgentMode bool, stdin os.FileMode) bool {
	return isAgentMode && stdin&os.ModeSocket != 0
}

// readStdinBody returns the request body piped to cmd, or nil when there is
// none.
func readStdinBody(cmd *cobra.Command) ([]byte, error) {
	if !HasStdinInput(cmd) {
		return nil, nil
	}
	in := cmd.InOrStdin()
	if in == os.Stdin {
		if stat, err := os.Stdin.Stat(); err == nil && silenceMeansNoBody(isAgentMode(), stat.Mode()) {
			return readStdinBounded(in, agentSocketWait)
		}
	}
	return readStdinBounded(in, 0)
}

// readStdinBounded reads r to EOF, giving up after StdinReadTimeout. When
// silenceLimit is positive and r delivers nothing at all within it, not even
// EOF, it returns no data and no error: there is no body.
//
// On either timeout the read goroutine is abandoned while it is still parked in
// read(2). That leaks one goroutine and its OS thread for the remaining life of
// the process, which is acceptable here and nowhere else: this runs once per
// invocation of a short-lived CLI that is about to exit. The alternative —
// putting the file descriptor into non-blocking mode — mutates the open file
// description that the parent shell shares, so it would corrupt the caller's
// terminal on any exit path that failed to restore it.
func readStdinBounded(r io.Reader, silenceLimit time.Duration) ([]byte, error) {
	type result struct {
		data []byte
		err  error
	}
	done := make(chan result, 1) // buffered so the abandoned goroutine can finish and exit
	first := &firstReadSignal{r: r, arrived: make(chan struct{})}

	go func() {
		data, err := io.ReadAll(first)
		done <- result{data: data, err: err}
	}()

	timer := time.NewTimer(StdinReadTimeout)
	defer timer.Stop()

	if silenceLimit > 0 {
		silence := time.NewTimer(silenceLimit)
		defer silence.Stop()
		select {
		case <-first.arrived:
		case <-silence.C:
			return nil, nil
		}
	}

	select {
	case res := <-done:
		return res.data, res.err
	case <-timer.C:
		return nil, fmt.Errorf(
			"%w after %s: stdin is open but sent no data and never closed.\n"+
				"If you did not mean to pipe a request body, redirect it: vf <command> </dev/null\n"+
				"If you did, make sure the producer closes its write end when it is finished",
			ErrStdinTimeout, StdinReadTimeout,
		)
	}
}

// firstReadSignal closes arrived once the first read from r returns, whether
// with data, EOF or an error.
type firstReadSignal struct {
	r       io.Reader
	once    sync.Once
	arrived chan struct{}
}

func (f *firstReadSignal) Read(p []byte) (int, error) {
	n, err := f.r.Read(p)
	f.once.Do(func() { close(f.arrived) })
	return n, err
}
